	/** 
	 * jumpstart the process by instantiating2 Insurer
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		insurerId = InsurerService.getInsurerInstance()
		.createInsurer( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		InsurerService.getInsurerInstance()
				.createInsurer( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.insurerSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Insurer : " + successValue.getInsurerId());
							  if (successValue.getInsurerId().equals(insurerId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfInsurerList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Insurer test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on insurer consumed")
					);
			subscriber.insurerSubscribe( insurerId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Insurer : " + successValue.getInsurerId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfInsurerList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on insurer for insurerId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Insurer. 
	 */
	protected Insurer read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Insurer" );

		Insurer entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Insurer with primary key" );
		msg.append( insurerId );
		
		InsurerFetchOneSummary fetchOneSummary = new InsurerFetchOneSummary( insurerId );

		try {
			entity = InsurerService.getInsurerInstance().getInsurer( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Insurer " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Insurer.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Insurer." );

		StringBuilder msg = new StringBuilder( "Failed to update a Insurer : " );        
		Insurer entity = read();
		UpdateInsurerCommand command = generateUpdateCommand();
		command.setInsurerId(entity.getInsurerId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Insurer." );

			// for use later on...
			insurerId = entity.getInsurerId();

			InsurerService proxy = InsurerService.getInsurerInstance();  

			proxy.updateInsurer( command ).get();

			LOGGER.info( "-- Successfully saved Insurer - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + insurerId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Insurer.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Insurer." );

		Insurer entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Insurer with id " + insurerId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Insurer with id " + insurerId );

			throw e;
		}

		try{
			InsurerService.getInsurerInstance().delete( new DeleteInsurerCommand( entity.getInsurerId() ) ).get();
			LOGGER.info( "-- Successfully deleted Insurer with id " + insurerId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Insurer with id " + insurerId );

			throw e;
		}
	}

	/**
	 * get all Insurers.
	 */
	protected List<Insurer> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Insurers:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Insurer : " );        
		List<Insurer> collection  = new ArrayList<>();

		try {
			// call the static get method on the InsurerService
			collection = InsurerService.getInsurerInstance().getAllInsurer();
			assertNotNull( collection, "An Empty collection of Insurer was incorrectly returned.");
			
			// Now print out the values
			Insurer entity = null;            
			Iterator<Insurer> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getInsurerId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

